import{_ as a,c as i,o as l,ae as o}from"./chunks/framework.BbFa6TS3.js";const u=JSON.parse('{"title":"工作流","description":"","frontmatter":{},"headers":[],"relativePath":"fe/ai/workflow.md","filePath":"fe/ai/workflow.md"}'),t={name:"fe/ai/workflow.md"};function r(n,e,h,s,f,c){return l(),i("div",null,e[0]||(e[0]=[o('<h1 id="工作流" tabindex="-1">工作流 <a class="header-anchor" href="#工作流" aria-label="Permalink to &quot;工作流&quot;">​</a></h1><h2 id="n8n" tabindex="-1">n8n <a class="header-anchor" href="#n8n" aria-label="Permalink to &quot;n8n&quot;">​</a></h2><p><a href="https://github.com/n8n-io/n8n" target="_blank" rel="noreferrer">https://github.com/n8n-io/n8n</a></p><p>n8n 是一个工作流自动化平台，它为技术团队提供了代码般的灵活性和无代码般的速度。n8n 拥有 400 多个集成、原生 AI 功能以及公平代码许可证，让您能够构建强大的自动化流程，同时完全掌控您的数据和部署。</p><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><ul><li>节点（Node）：每个节点代表一个功能，比如发送邮件、请求 API、处理数据等。</li><li>工作流（Workflow）：由多个节点组成，定义了自动化的业务流程。</li><li>触发器（Trigger）：工作流的起点，比如定时触发、Webhook、接收邮件等。</li></ul><h3 id="常用功能" tabindex="-1">常用功能 <a class="header-anchor" href="#常用功能" aria-label="Permalink to &quot;常用功能&quot;">​</a></h3><ul><li>内置 400+ 集成：如 Slack、Telegram、GitHub、Notion、MySQL、各类邮件服务等。</li><li>支持自定义代码：可在节点中直接写 JavaScript/Python 处理数据。</li><li>AI 能力：内置 OpenAI、LangChain 等 AI 节点，可实现智能问答、内容生成等。</li><li>可视化调试：每个节点可单步调试，查看输入输出数据。</li></ul><h3 id="自动化场景" tabindex="-1">自动化场景 <a class="header-anchor" href="#自动化场景" aria-label="Permalink to &quot;自动化场景&quot;">​</a></h3><p>场景一：自动同步表单数据到 Google Sheets</p><ol><li>添加触发器节点：选择“Webhook”节点，设置为 POST，n8n 会生成一个 Webhook 地址。</li><li>添加 Google Sheets 节点：搜索并添加“Google Sheets”节点，配置你的 Google 账号，选择“添加行”操作。</li><li>连接节点：将 Webhook 节点输出连接到 Google Sheets 节点输入。</li><li>保存并激活工作流：点击右上角“激活”按钮，n8n 会监听 Webhook 地址，收到数据后自动写入表格。</li></ol><p>场景二：定时抓取新闻并推送到微信/钉钉</p><ol><li>添加定时触发器：选择“Cron”节点，设置定时规则（如每小时）。</li><li>添加 HTTP 请求节点：用于抓取新闻 API。</li><li>添加消息推送节点：比如“DingTalk”或“Wechat”节点，配置推送内容。</li><li>串联节点：按顺序连接，形成完整流程。</li></ol><h3 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to &quot;参考资源&quot;">​</a></h3><ul><li>工作流模板库：<a href="https://n8n.io/workflows" target="_blank" rel="noreferrer">https://n8n.io/workflows</a></li><li>社区教程：<a href="https://community.n8n.io/c/tutorials/28" target="_blank" rel="noreferrer">https://community.n8n.io/c/tutorials/28</a></li><li>集成列表：<a href="https://n8n.io/integrations" target="_blank" rel="noreferrer">https://n8n.io/integrations</a></li></ul><h2 id="dify" tabindex="-1">Dify <a class="header-anchor" href="#dify" aria-label="Permalink to &quot;Dify&quot;">​</a></h2><p><a href="https://github.com/langgenius/dify" target="_blank" rel="noreferrer">https://github.com/langgenius/dify</a></p><p>Dify 是一个开源的 LLM 应用开发平台。Dify 直观的界面融合了 AI 工作流、RAG 流水线、代理功能、模型管理、可观察性功能等，让您能够快速从原型开发过渡到生产环境。</p>',18)]))}const p=a(t,[["render",r]]);export{u as __pageData,p as default};
